INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-031', 'SW', 'P2', 'OPEN', NULL, NULL, 'THREE FIELDS WITH NO REPAIR PATH, FOUND BY A CODE REVIEW OF BATCH 17 ADMISSIONS. (1) evidence_sources.journal_name is NULL on all 25 rows corpus-wide and correct-source field list does not include it, so the venue of every source in this project exists only in prose and in retrieval payloads, never in a queryable column -- the bibliography compiler cannot render a journal name for anything. (2) evidence_population_match has NO AMEND VERB. add-population-match does take --sample-size and I simply did not pass it for REF-01003, whose N is stated in the same INSERT free text (23 men and women); the deliberate absence of a uniqueness refusal (CLAUDE.md section 4) means the only way to add it now is a SECOND row, which reads as a DISSENTING GRADE and would be a false contest. So a routine omission is unrepairable by design. (3) evidence_sources.author_count is NULL on all 25 rows and that is CORRECT, not a defect -- migration 063 writer-retired it along with first_author_last, first_author_first and is_corporate_primary; authorship lives in evidence_source_authors and is derived by v_evidence_authors. Recorded because the review flagged it as a defect and it is not, and a future reader comparing 0-of-25 across these three columns needs to know which nulls are design and which are damage.', '2026-09-18 22:08', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 22:08', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);
