INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (77, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'wheelchair users perceived running slope cross slope ramp Borg perceived exertion maximum 7% Vredenburgh', NULL, 'consensus', 'scoping', 'none', 10, 10, 2, NULL, NULL, NULL, 1, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 22:06', 'THE SEARCH THAT ACTUALLY SURFACED THIS BATCH TWO ADMISSIONS, logged retrospectively because it was omitted at the time. Candidates 107 and 108 were originally attached to exec 71 -- the Co-1 DPO access-audit search whose own findings_note reads ZERO YIELD -- so the batch two best sources hung off a search reporting that it found nothing, and no search_admissions edge existed for either. Both corrected here. Consensus returned the Vredenburgh record (corroborating REF-01002 at index level, still not full text) and, in the same result set, Longmuir et al. 2003 and Kim et al. 2010, which became REF-01003 and REF-01004.', 0, 'BACKFILL, AND THE PRIOR IS THE ABSENCE OF ONE -- recorded as such rather than reconstructed. This search RAN during batch 17 as part of the REF-01002 retrieval hunt and was NEVER LOGGED, which a code review caught. No prior was written before it because it was not framed as a screening search at the time; it was a locator hunt that incidentally surfaced two admissible sources. DR-2026-05-09 forbids writing a prior after seeing results, so none is invented here. What IS recorded: the query verbatim, the engine, and that the omission is the defect.');

